# Let's try to solve Langford L(2,12) using OR-Tools CP-SAT if available
try:
    from ortools.sat.python import cp_model
    print("OR-Tools available")
except Exception as e:
    print("OR-Tools not available:", e)

seq = [4, 1, 3, 1, 12, 4, 3, 7, 5, 8, 10, 11, 9, 6, 5, 7, 2, 12, 8, 2, 6, 10, 9, 11]

# Verify
def verify_langford(seq, n):
    if len(seq) != 2*n:
        return False
    for v in range(1, n+1):
        positions = [i for i, x in enumerate(seq) if x == v]
        if len(positions) != 2:
            print(f"Value {v} appears {len(positions)} times")
            return False
        if positions[1] - positions[0] != v + 1:
            print(f"Value {v} has positions {positions}, distance = {positions[1] - positions[0]}, expected = {v+1}")
            return False
    print("Verification passed!")
    return True

verify_langford(seq, 12)
